mat2 rotMat(float r){ return  mat2(cos(r), -sin(r), sin(r), cos(r)); }

vec3 rotX(in vec3 p, float r)
{
    p.yz *= rotMat(r); return p;
}

vec3 rotY(in vec3 p, float r)
{
    p.xz *= rotMat(r); return p;
}

vec3 rotZ(in vec3 p, float r)
{
    p.xy *= rotMat(r); return p;
}


vec3 rot(vec3 v, in vec3 k, float t) // rotates point v t radians around axis k.
{
    k = normalize(k);
    return mix(k*dot(k,v), v, cos(t)) + cross(k, v)*sin(t);
}

vec3 planeIntersect(in vec3 ro, vec3 rd, float y, out bool hit)
{
    hit = sign(-rd.y) == sign(ro.y-y);
    ro.xz = ro.xz+rd.xz*(y-ro.y)/rd.y;
    return vec3(ro.x, y, ro.z);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord-iResolution.xy*0.5)/iResolution.y;
    vec2 m =  (iMouse.xy-iResolution.xy*0.5)/iResolution.y*step(0.01, iMouse.z);

    vec2 rot = vec2(3.14*0.5, 0)-m.xy;
    vec3 ro = vec3(0, 1, 0);
    vec3 rd = rotY(rotX(normalize(vec3(uv, 1)), rot.y), rot.x);

    bool hit;
    vec3 pli = planeIntersect(ro, rd, 0., hit);

    vec3 env = texture(iChannel0, mix(reflect(rd, normalize(vec3(0, 1, 0)+0.02*(texture(iChannel1, 0.1*(pli.xyz+iTime)).xyz-0.5))), rd, 1.-float(hit))).rgb;

    fragColor = vec4(env, 1.0);
}
